Source code in <code>tuney/app/audio_recorder.py</code> <pre><code>def on_transport_state(
    self,
    change: StateChange,
    player: Player,
    comment_factory: Callable[[], Callable[[], str]],
    path: Path | None = None,
) -&gt; bool:
    instrument(
        'audio recorder transport',
        old_state=change.old_state,
        state=change.state,
        action=change.action,
    )
    if change.action == Action.save:
        if path is None:
            return False
        if change.old_state == State.recording:
            self.stop(player)
        self.save(path)
    elif change.action == Action.clear:
        if change.old_state == State.recording:
            self.stop(player)
        self.clear()
    elif change.action == Action.stop:
        if change.old_state == State.recording:
            self.stop(player)
    elif change.state == State.paused:
        self.stop(player)
    else:
        self.start(player, comment_factory)
    return True
