    from .text_timing import text_timing_active_indexes

    instrument(
        'key recorder replay start',
        is_replaying=state.main_window.is_replaying,
    )
    sequencer, self.sequencer = self.sequencer, None
    if sequencer:
        instrument('key recorder stop old sequencer')
        sequencer.stop()
    state.player.stop_all()
    self.speech = None

    self.replay_text = ''
    if state.main_window.is_replaying:
        char_presses = state.replay_char_presses()
        instrument('key recorder replay events', count=len(char_presses))
        active_indexes = text_timing_active_indexes(char_presses)
        if state.show_text_timings:
            state.main_window.update_text_display()
            state.main_window.ui.set_active_text_timing(None)
        else:
            state.main_window.ui.set_text(self.replay_text)
            state.main_window.ui.set_play_cursor(0)

        def deliver(char_press: CharPress | None) -&gt; None:
            if (
                self.sequencer is not sequencer
                or not state.main_window.is_replaying
            ):
                return
            if char_press:
                if state.show_text_timings:
                    state.main_window.ui.set_active_text_timing(
                        active_indexes.get(id(char_press)),
                    )
                if char_press.is_press:
                    self.replay_text += char_press.char
                    if not state.show_text_timings:
                        state.main_window.ui.set_text(self.replay_text)
                        state.main_window.ui.set_play_cursor(
                            len(self.replay_text),
                        )
                state.play_char(char_press)
            else:
                self.finish_replay(state)

        def callback(char_press: CharPress | None) -&gt; None:
            state.main_window.after(0, deliver, char_press)

        sequencer = self.sequencer = Sequencer(
            char_presses=char_presses,
            callback=callback,
        )

        def start_replay() -&gt; None:
            state.main_window.ui.start_loop_clock()
            instrument('key recorder sequencer start')
            sequencer.start()

        if state.use_speech and char_presses:
            request = state.player.speech_request(
                speech_phrases(char_presses, state.use_phrase_mode),
                state.speech_level,
                state.speech_speed,
                state.speech_voice,
            )
            if speech := state.player.prepared_speech.take(request):
                self.speech = speech
                state.player.play_speech(speech)
                start_replay()
            else:

                def ready(speech: SpeechPlayback | None, error: str | None) -&gt; None:
                    if (
                        self.sequencer is not sequencer
                        or not state.main_window.is_replaying
                    ):
                        return
                    if error is not None:
                        report_error(f'Could not prepare speech: {error}')
                        state.stop_replaying()
                        return
                    if speech is not None:
                        self.speech = speech
                        state.player.play_speech(speech)
                    start_replay()

                def prepare() -&gt; None:
                    try:
                        speech = render_speech(request)
                    except (
                        ImportError,
                        OSError,
                        RuntimeError,
                        ValueError,
                        MemoryError,
                    ) as error:
                        state.main_window.after(0, ready, None, str(error))
                    else:
                        state.main_window.after(0, ready, speech, None)

                start_thread(prepare)
        else:
            start_replay()
    else:
        state.main_window.update_text_display()
        state.main_window.ui.set_play_cursor(None)
        state.main_window.ui.set_active_text_timing(None)
    instrument('key recorder replay end')
