Source code in <code>tuney/app/key_recorder.py</code> <pre><code>def speech_phrases(
    char_presses: list[CharPress], use_phrase_mode: bool = True
) -&gt; list[SpeechPhrase]:
    if not use_phrase_mode:
        text = ''.join(c.char for c in char_presses if c.is_press).strip()
        start = next(
            (
                c.time / 1000
                for c in char_presses
                if c.is_press and not c.char.isspace()
            ),
            None,
        )
        if text and start is not None:
            return [SpeechPhrase(text=text, start=start)]
        return []

    phrases = []
    phrase = ''
    start = None
    for c in char_presses:
        if not c.is_press:
            continue
        if start is None and not c.char.isspace():
            start = c.time / 1000
        phrase += c.char
        if c.char in PHRASE_PUNCTUATION and start is not None:
            phrases.append(SpeechPhrase(text=phrase.strip(), start=start))
            phrase = ''
            start = None
    if phrase.strip() and start is not None:
        phrases.append(SpeechPhrase(text=phrase.strip(), start=start))
    return phrases
</code></pre>

