Source code in <code>tuney/scale/nearest_note.py</code> <pre><code>def nearest_note(
    tuning: Tuning, frequency: float, epsilon: float = EPSILON
) -&gt; int | tuple[int, int]:
    below = above = 0
    while tuning(below) &gt; frequency:
        below = (2 * below) or -0x40
    while tuning(above) &lt; frequency:
        above = (2 * above) or 0x40
    while (above - below) &gt; 1:
        mid = (below + above) // 2
        f = tuning(mid)
        if abs(f - frequency) &lt; epsilon:
            return mid
        elif f &lt; frequency:
            below = mid
        else:
            above = mid
    return below, above
</code></pre>

