Source code in <code>tuney/ui/main_window.py</code> <pre><code>def visible_restored_window_state(
    window: MainWindow, window_state: WindowState
) -&gt; WindowState:
    screen = None
    if QtWidgets.QApplication.instance() is not None:
        screen = QtWidgets.QApplication.screenAt(QPoint(window_state.x, window_state.y))
    if screen is None:
        screen_method = getattr(window, 'screen', None)
        if callable(screen_method):
            screen = screen_method()
    if screen is None and QtWidgets.QApplication.instance() is not None:
        screen = QtWidgets.QApplication.primaryScreen()
    if screen is None:
        return window_state
    available = screen.availableGeometry()
    y = max(window_state.y, available.y())
    if y == window_state.y:
        return window_state
    return WindowState(
        x=window_state.x,
        y=y,
        width=window_state.width,
        height=window_state.height,
    )
</code></pre>

Source code in <code>tuney/ui/midi_devices.py</code> <pre><code>def watch_midi_devices(window: MainWindow, stop_event: Event) -&gt; None:
    names = midi_names()
    names = [
        new if new is not None else old
        for new, old in zip(probe_midi_names(), names, strict=True)
    ]
    if stop_event.is_set():
        return
    midi_names.replace(names)
    while not stop_event.wait(MIDI_DEVICE_POLL_IN_SECONDS):
        updated = [
            new if new is not None else old
            for new, old in zip(probe_midi_names(), names, strict=True)
        ]
        if stop_event.is_set():
            return
        if updated != names:
            names = updated
            midi_names.replace(updated)
            try:
                window.midi_device_queue.put_nowait(updated)
            except Full:
                try:
                    window.midi_device_queue.get_nowait()
                except Empty:
                    pass
                window.midi_device_queue.put_nowait(updated)
</code></pre>

